import { test, expect } from '@playwright/test';

test.describe('Profile Update Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should display confirmation message after successful profile update', async ({ page }) => {
    // Verify profile form is visible
    const profileForm = page.getByRole('form', { name: /profile/i });
    await expect(profileForm).toBeVisible();

    // Get and fill first name input using getByLabel
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('John');

    // Get and fill last name input using getByLabel
    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Doe');

    // Get and fill email input using getByLabel
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    // Get and click save button using getByRole
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Wait for confirmation message to appear
    const confirmationMessage = page.getByText(/profile updated successfully/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify confirmation message has success styling
    await expect(confirmationMessage).toHaveClass(/success-message/);

    // Verify profile details are updated
    const firstNameDisplay = page.getByText('John');
    await expect(firstNameDisplay).toBeVisible();

    const lastNameDisplay = page.getByText('Doe');
    await expect(lastNameDisplay).toBeVisible();
  });

  test('should not display confirmation message when profile update fails', async ({ page }) => {
    // Get and fill first name input using getByLabel
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('InvalidName');

    // Get and fill last name input using getByLabel
    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Doe');

    // Get and fill email input using getByLabel
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('invalid-email');

    // Get and click save button using getByRole
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/error updating profile/i);
    await expect(errorMessage).toBeVisible();

    // Verify confirmation message does not exist
    const confirmationMessage = page.getByText(/profile updated successfully/i);
    await expect(confirmationMessage).not.toBeVisible();

    // Verify error message has error styling
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify form fields are still populated with invalid data
    await expect(firstNameInput).toHaveValue('InvalidName');
  });
});
